#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/ztest.h> 
#include <zephyr/sys/mm_drv.h>

/*
 * Some of these tests are for the device API, some are for the device
 * driver implementation itself.
 */

struct init_record {
	const struct device *dev;
	int init_res;
};

#define MAX_INIT_RECORDS 8
static struct init_record init_records[MAX_INIT_RECORDS];
static struct init_record *rp = init_records;
static bool record_all_inits;

static int init_fn(const struct device *dev)
{
	if (record_all_inits || k_is_pre_kernel()) {
		if (rp < init_records + MAX_INIT_RECORDS) {
			rp->dev = dev;
			rp->init_res = 0;
			rp++;
		}
	}
	return 0;
}

static int init_fn_fail(const struct device *dev)
{
	if (record_all_inits || k_is_pre_kernel()) {
		if (rp < init_records + MAX_INIT_RECORDS) {
			rp->dev = dev;
			rp->init_res = -1;
			rp++;
		}
	}
	return -1;
}

/* Create a set of devices with different init levels and priorities */
DEVICE_DEFINE(device_test_pre_kernel_1, "pre_kernel_1", init_fn, NULL, NULL,
		NULL, PRE_KERNEL_1, 0, NULL);

DEVICE_DEFINE(device_test_pre_kernel_2, "pre_kernel_2", init_fn, NULL, NULL,
		NULL, PRE_KERNEL_2, 0, NULL);

DEVICE_DEFINE(device_test_post_kernel, "post_kernel", init_fn, NULL, NULL,
		NULL, POST_KERNEL, 0, NULL);

DEVICE_DEFINE(device_test_application, "application", init_fn, NULL, NULL,
		NULL, APPLICATION, 0, NULL);

DEVICE_DEFINE(device_test_post_kernel_fail, "post_kernel_fail", init_fn_fail,
		NULL, NULL, NULL, POST_KERNEL, 1, NULL);

static int binding_test_init(const struct device *dev)
{
	return 0;
}

/* For device_get_binding() test */
DEVICE_DEFINE(device_binding_test, "device_binding_test", binding_test_init, NULL, NULL,
		NULL, APPLICATION, 0, NULL);

/* For dynamic name test */
static char dynamic_name[] = "dynamic_name";

static int dynamic_name_init(const struct device *dev)
{
	return 0;
}

DEVICE_DEFINE(device_dynamic_name, dynamic_name, dynamic_name_init, NULL, NULL,
		NULL, APPLICATION, 0, NULL);

/*
 * test cases
 */

/**
 * @brief Test that device binding works
 *
 * The device binding test will get the device object of the pre-defined
 * device object "device_binding_test" and check the device name.
 *
 * @ingroup kernel_device_tests
 *
 * @see DEVICE_DEFINE()
 */
static void test_device_binding(void)
{
	const struct device *dev;

	dev = device_get_binding("device_binding_test");
	zassert_not_null(dev, "device_get_binding() failed");
	zassert_str_equal(dev->name, "device_binding_test",
			"device name not matched");

	dev = device_get_binding("no_such_device");
	zassert_is_null(dev, "device_get_binding() should have failed");
}

/**
 * @brief Test that device ready check works
 *
 * The device ready check test will check the pre-defined device object
 * "device_binding_test" and check its ready status.
 *
 * @ingroup kernel_device_tests
 *
 * @see device_is_ready()
 */
static void test_device_ready(void)
{
	const struct device *dev;

	dev = device_get_binding("device_binding_test");
	zassert_not_null(dev, "device_get_binding() failed");
	zassert_true(device_is_ready(dev), "device should be ready");

	dev = device_get_binding("post_kernel_fail");
	zassert_not_null(dev, "device_get_binding() failed");
	zassert_false(device_is_ready(dev), "device should not be ready");
}

/**
 * @brief Test device initialization flow
 *
 * This test case tests the device initialization flow by creating a set of
 * dummy devices and check the initialization records.
 *
 * @ingroup kernel_device_tests
 *
 * @see DEVICE_DEFINE()
 */
static void test_device_init_flow_func(void)
{
	/*
	 * Test that all devices are initialized and the init function
	 * is called in the correct order.
	 */
	zassert_equal(rp - init_records, 5, "incorrect init record count");
	zassert_true(init_records[0].dev == &device_test_pre_kernel_1,
			"bad dev");
	zassert_true(init_records[1].dev == &device_test_pre_kernel_2,
			"bad dev");
	zassert_true(init_records[2].dev == &device_test_post_kernel,
			"bad dev");
	zassert_true(init_records[3].dev == &device_test_post_kernel_fail,
			"bad dev");
	zassert_true(init_records[4].dev == &device_test_application,
			"bad dev");

	zassert_equal(init_records[0].init_res, 0, "bad res");
	zassert_equal(init_records[1].init_res, 0, "bad res");
	zassert_equal(init_records[2].init_res, 0, "bad res");
	zassert_equal(init_records[3].init_res, -1, "bad res");
	zassert_equal(init_records[4].init_res, 0, "bad res");
}

/**
 * @brief Test pre-kernel device initialization detection
 *
 * This test case tests that only PRE_KERNEL_1 and PRE_KERNEL_2 devices are
 * initialized before the kernel is started.
 *
 * @ingroup kernel_device_tests
 *
 * @see k_is_pre_kernel()
 */
static void device_test_pre_kernel_detection(void)
{
	/*
	 * Test that only PRE_KERNEL_1 and PRE_KERNEL_2 devices are
	 * initialized before the kernel is started.
	 */
	zassert_equal(rp - init_records, 2U, "rp - init_records not equal to 2U");
	zassert_true(init_records[0].dev == &device_test_pre_kernel_1,
			"bad dev");
	zassert_true(init_records[1].dev == &device_test_pre_kernel_2,
			"bad dev");
	zassert_equal(init_records[0].init_res, 0, "bad res");
	zassert_equal(init_records[1].init_res, 0, "bad res");
}

static void test_dynamic_name(void)
{
	const struct device *dev;

	dev = device_get_binding(dynamic_name);
	zassert_not_null(dev, "device_get_binding() failed");
	zassert_str_equal(dev->name, dynamic_name, "device name not matched");
}

#ifdef CONFIG_USERSPACE
static void test_device_from_user(void)
{
	const struct device *dev = device_get_binding("device_binding_test");

	zassert_not_null(dev, "device_get_binding() failed");

	/* Syscall to verify that the device object is valid from user mode */
	k_object_access_grant(dev, k_current_get());
	zassert_true(z_impl_device_is_ready(dev), "device should be ready");
}
#endif

static void *device_test_setup(void)
{
	rp = init_records;
	(void)memset(init_records, 0, sizeof(init_records));

	return NULL;
}

/*
 * The pre-kernel detection test needs to be in its own suite since it
 * depends on global state established at boot.
 */
ZTEST_SUITE(device_pre_kernel, NULL, NULL, NULL, NULL, NULL);

ZTEST(device_pre_kernel, test_pre_kernel_detection)
{
	device_test_pre_kernel_detection();
}

/*
 * The remaining tests can be in a second suite that resets the
 * global state.
 */
ZTEST_SUITE(device_api, NULL, device_test_setup, NULL, NULL, NULL);

ZTEST(device_api, test_device_binding)
{
	test_device_binding();
}

ZTEST(device_api, test_device_ready)
{
	test_device_ready();
}

ZTEST(device_api, test_device_init_flow)
{
	/*
	 * Re-run the init process on a clean slate. We can do this
	 * because we are in a thread and the real init has finished.
	 */
	record_all_inits = true;
	z_sys_init_run_level(INIT_LEVEL_PRE_KERNEL_1);
	z_sys_init_run_level(INIT_LEVEL_PRE_KERNEL_2);
	z_sys_init_run_level(INIT_LEVEL_POST_KERNEL);
	z_sys_init_run_level(INIT_LEVEL_APPLICATION);
	z_sys_init_run_level(INIT_LEVEL_SMP);
	record_all_inits = false;

	test_device_init_flow_func();
}

ZTEST(device_api, test_dynamic_name)
{
	test_dynamic_name();
}

#ifdef CONFIG_USERSPACE
ZTEST_USER(device_api, test_device_from_user)
{
	test_device_from_user();
}
#endif
